public class ControllerServlet extends HttpServlet {
  protected void doGet(HttpServletRequest req, HttpServletResponse resp)
      throws ServletException, IOException {
    Command command = CommandFactory.create(req.getParameter("action"));  // dispatcher
    String next = command.execute(req, resp);   // worker fills request-scoped model
    getServletContext().getRequestDispatcher(next).forward(req, resp);    // view
  }
}
